def create_categories_from_products(apps, schema_editor):
    """
    Cria objetos Category baseado on strings de categoria dos produtos.
    Mapeia cada produto para a categoria correspondente.
    """
    Product = apps.get_model('beckend', 'Product')
    Category = apps.get_model('beckend', 'Category')
    
    # Pega todas as categorias únicas dos produtos
    unique_categories = Product.objects.values_list('category', flat=True).distinct()
    
    category_map = {}
    for category_name in unique_categories:
        if category_name:
            category_obj, created = Category.objects.get_or_create(
                name=category_name,
                slug=slugify(category_name)
            )
            category_map[category_name] = category_obj.id
    
    # Atualiza os produtos para apontar as categories corretas
    for product in Product.objects.all():
        if product.category in category_map:
            product.category_id = category_map[product.category]
            product.save()


